// Build platform-specific comment reply request
const accounts = $input.first().json;
const account = Array.isArray(accounts) ? accounts[0] : accounts;
const body = $('Webhook').first().json.body;

if (!account || !account.access_token) {
  throw new Error(`No connected account found for id ${body.account_id}`);
}

const platform = account.platform;
const token = account.access_token;
const replyText = body.reply_body;

// The message_id is the platform-native ID of the comment/post being replied to
// Stored in social_messages.platform_msg_id — must be passed in the webhook payload
const platformMsgId = body.platform_msg_id; 

let apiUrl = '';
let apiBody = {};
let extraHeaders = {};

switch (platform) {
  case 'linkedin': {
    // LinkedIn: reply to a share/post as a comment
    apiUrl = `https://api.linkedin.com/v2/socialActions/${encodeURIComponent(platformMsgId)}/comments`;
    apiBody = {
      actor: `urn:li:person:${account.account_id}`,
      message: { text: replyText }
    };
    extraHeaders = {
      'Authorization': `Bearer ${token}`,
      'X-Restli-Protocol-Version': '2.0.0'
    };
    break;
  }

  case 'facebook': {
    // Facebook: reply to a comment
    apiUrl = `https://graph.facebook.com/v18.0/${platformMsgId}/comments`;
    apiBody = { message: replyText, access_token: token };
    break;
  }

  case 'instagram': {
    // Instagram: reply to a comment on a media object
    apiUrl = `https://graph.facebook.com/v18.0/${platformMsgId}/replies`;
    apiBody = { message: replyText, access_token: token };
    break;
  }

  case 'x':
  case 'twitter': {
    // X (Twitter): reply to a tweet
    apiUrl = 'https://api.twitter.com/2/tweets';
    const tweetText = replyText.length > 280 ? replyText.slice(0, 277) + '...' : replyText;
    apiBody = {
      text: tweetText,
      reply: { in_reply_to_tweet_id: platformMsgId }
    };
    extraHeaders = { 'Authorization': `Bearer ${token}` };
    break;
  }

  case 'tiktok': {
    // TikTok: comment on a video
    apiUrl = 'https://open.tiktokapis.com/v2/comment/create/';
    apiBody = {
      video_id: platformMsgId,
      text: replyText.slice(0, 150)
    };
    extraHeaders = { 'Authorization': `Bearer ${token}` };
    break;
  }

  default:
    throw new Error(`Unsupported platform: ${platform}`);
}

return [{
  apiUrl,
  apiBody: JSON.stringify(apiBody),
  extraHeaders: JSON.stringify(extraHeaders),
  platform,
  run_id: body.run_id,
  org_id: body.org_id,
  message_id: body.message_id,
  reply_id: body.reply_id,
  callback_url: body.callback_url
}];

// Mark message as replied in Supabase
const buildData = $('Build Reply Request').first().json;
const supaUrl = process.env.SUPABASE_URL;
const supaKey = process.env.SUPABASE_SERVICE_ROLE_KEY;

if (supaUrl && supaKey) {
  // Update social_message status
  await $helpers.httpRequest({
    method: 'PATCH',
    url: `${supaUrl}/rest/v1/social_messages?id=eq.${buildData.message_id}`,
    headers: {
      'apikey': supaKey,
      'Authorization': `Bearer ${supaKey}`,
      'Content-Type': 'application/json',
      'Prefer': 'return=minimal'
    },
    body: JSON.stringify({ status: 'replied', is_read: true })
  });

  // Update reply record status
  if (buildData.reply_id) {
    await $helpers.httpRequest({
      method: 'PATCH',
      url: `${supaUrl}/rest/v1/social_replies?id=eq.${buildData.reply_id}`,
      headers: {
        'apikey': supaKey,
        'Authorization': `Bearer ${supaKey}`,
        'Content-Type': 'application/json',
        'Prefer': 'return=minimal'
      },
      body: JSON.stringify({ status: 'sent', sent_at: new Date().toISOString() })
    });
  }
}

return [buildData];

const crypto = require('crypto');
const data = $input.first().json;

const payload = {
  workflow_type: 'social_classification',
  status: 'complete',
  run_id: data.run_id,
  org_id: data.org_id,
  reply_id: data.reply_id,
  reply_status: 'sent'
};

const body = JSON.stringify(payload);
const secret = process.env.N8N_HMAC_SECRET || '';
const signature = crypto.createHmac('sha256', secret).update(body).digest('hex');

return [{ body, signature, callback_url: data.callback_url }];

const crypto = require('crypto');
const wb = $('Webhook').first().json.body;
const errMsg = $input.first().json.message || 'Reply failed';

const payload = {
  workflow_type: 'social_classification',
  status: 'failed',
  run_id: wb.run_id,
  org_id: wb.org_id,
  reply_id: wb.reply_id,
  reply_status: 'failed',
  error_message: errMsg
};

const body = JSON.stringify(payload);
const secret = process.env.N8N_HMAC_SECRET || '';
const signature = crypto.createHmac('sha256', secret).update(body).digest('hex');

return [{ body, signature, callback_url: wb.callback_url }];
